import { forwardRef, useEffect, useId, useMemo, useRef, useState } from 'react';
import type { DialogHTMLAttributes, KeyboardEvent } from 'react';
import { cx } from '@/lib/cx';
import { useStrings } from '@/lib/i18n';
import './search-command.css';

/**
 * B16 · SearchCommand (⌘K) — the keyboard front door every 76° app ships.
 * Dialog-anatomy palette: mono input, grouped results, ↑/↓ + Enter, Esc.
 */
export interface CommandItem {
  id: string;
  group: string;
  label: string;
  /** Mono hint on the right, e.g. an ID or shortcut. */
  hint?: string;
  keywords?: string;
  /** Listed but not pickable: arrow keys skip it and a click does nothing. */
  disabled?: boolean;
}

export interface SearchCommandProps
  extends Omit<DialogHTMLAttributes<HTMLDialogElement>, 'open' | 'onClose' | 'children'> {
  items: CommandItem[];
  onPick: (item: CommandItem) => void;
  placeholder?: string;
  /** Bind ⌘K/Ctrl-K globally (default true). */
  bindShortcut?: boolean;
  /**
   * Called when the shortcut opens the palette. Pass the same setter that
   * drives `open` — without it the shortcut opens the dialog imperatively
   * and `open` stays false, so the next onClose() has nothing to close.
   */
  onOpen?: () => void;
}

export function useSearchCommand() {
  const [open, setOpen] = useState(false);
  return { open, show: () => setOpen(true), hide: () => setOpen(false) };
}

export const SearchCommand = forwardRef<HTMLDialogElement, SearchCommandProps & { open: boolean; onClose: () => void }>(function SearchCommand({
  open,
  onClose,
  items,
  onPick,
  placeholder: placeholderProp,
  bindShortcut = true,
  onOpen,
  className,
  onCancel,
  onClick,
  ...rest
}, forwarded) {
  const tr = useStrings();
  const placeholder = placeholderProp ?? tr.searchEllipsis;
  /* Per-instance ids: two palettes on one page used to share one listbox id. */
  const uid = useId();
  const listId = `${uid}-list`;
  const optionId = (id: string) => `${uid}-opt-${id}`;
  const ref = useRef<HTMLDialogElement | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const [query, setQuery] = useState('');
  const [activeIdx, setActiveIdx] = useState(0);

  useEffect(() => {
    if (!bindShortcut) return;
    function onKey(e: globalThis.KeyboardEvent) {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        if (ref.current?.open) onClose();
        else if (onOpen) onOpen();
        else ref.current?.showModal();
      }
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [bindShortcut, onClose, onOpen]);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) {
      el.showModal();
      setQuery('');
      setActiveIdx(0);
      inputRef.current?.focus();
    }
    if (!open && el.open) el.close();
  }, [open]);

  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    const hits = q
      ? items.filter((i) => `${i.label} ${i.group} ${i.keywords ?? ''}`.toLowerCase().includes(q))
      : items;
    return hits.slice(0, 12);
  }, [items, query]);

  const groups = useMemo(() => {
    const map = new Map<string, CommandItem[]>();
    for (const item of results) {
      const list = map.get(item.group) ?? [];
      list.push(item);
      map.set(item.group, list);
    }
    return [...map.entries()];
  }, [results]);

  /* Steps from `from` toward `dir` to the nearest enabled result; stays put at the edge. */
  function stepTo(from: number, dir: number) {
    for (let i = from + dir; i >= 0 && i < results.length; i += dir) if (!results[i].disabled) return i;
    return from;
  }

  /* v0.11 · a new query resets to the FIRST ENABLED result, not row 0 —
     a disabled row 0 left Enter doing nothing on the very first keystroke. */
  useEffect(() => {
    if (results[activeIdx]?.disabled) setActiveIdx(stepTo(-1, 1));
  }, [results]);

  function onKeyDown(e: KeyboardEvent) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIdx((i) => stepTo(i, 1));
    }
    if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIdx((i) => stepTo(i, -1));
    }
    if (e.key === 'Enter' && results[activeIdx] && !results[activeIdx].disabled) {
      e.preventDefault();
      onPick(results[activeIdx]);
      onClose();
    }
  }

  let flatIdx = -1;

  return (
    <dialog
      {...rest}
      ref={(node) => {
        ref.current = node;
        if (typeof forwarded === 'function') forwarded(node);
        else if (forwarded) forwarded.current = node;
      }}
      className={cx('sv-command', className)}
      aria-label={rest['aria-label'] ?? tr.search}
      onCancel={(e) => {
        onCancel?.(e);
        e.preventDefault();
        onClose();
      }}
      onClick={(e) => {
        onClick?.(e);
        if (e.target === ref.current) onClose();
      }}
    >
      <div className="sv-command__panel" onKeyDown={onKeyDown}>
        <input
          ref={inputRef}
          className="sv-command__input"
          type="text"
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={results[activeIdx] ? optionId(results[activeIdx].id) : undefined}
          placeholder={placeholder}
          aria-label={placeholder}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setActiveIdx(0);
          }}
        />
        <ul className="sv-command__list" id={listId} role="listbox" aria-label={tr.results}>
          {groups.map(([group, groupItems]) => (
            /* v0.11 · a listbox may contain groups of options, and a group
               is named by its header — the old <li><p> sat in the listbox as
               content no option role could describe. */
            <li key={group} role="presentation">
              <p className="sv-command__group sv-mono" id={`${listId}-g-${group.replace(/\W+/g, '-')}`}>
                {group}
              </p>
              <ul role="group" aria-labelledby={`${listId}-g-${group.replace(/\W+/g, '-')}`}>
                {groupItems.map((item) => {
                  flatIdx += 1;
                  const idx = flatIdx;
                  return (
                    <li
                      key={item.id}
                      id={optionId(item.id)}
                      role="option"
                      aria-selected={idx === activeIdx}
                      aria-disabled={item.disabled || undefined}
                      className={cx('sv-command__item', idx === activeIdx && 'sv-command__item--active')}
                      onMouseEnter={() => !item.disabled && setActiveIdx(idx)}
                      onMouseDown={(e) => e.preventDefault()}
                      onClick={() => {
                        if (item.disabled) return;
                        onPick(item);
                        onClose();
                      }}
                    >
                      <span>{item.label}</span>
                      {item.hint && <span className="sv-command__hint sv-mono">{item.hint}</span>}
                    </li>
                  );
                })}
              </ul>
            </li>
          ))}
          {results.length === 0 && (
            <li className="sv-command__none" role="presentation">
              {tr.noResultsFor(query)}
            </li>
          )}
        </ul>
      </div>
    </dialog>
  );
});

/* B16 · SearchCommand */

@layer sv-components {
  .sv-command {
    width: min(560px, calc(100vw - var(--sv-s7)));
    margin-top: 12vh;
    padding: 0;
    border: 0;
    border-radius: var(--sv-r);
    background: var(--sv-paper);
    box-shadow: var(--sv-shadow);
  }

  .sv-command::backdrop {
    background: var(--sv-scrim);
  }

  .sv-command__input {
    width: 100%;
    padding: var(--sv-s4) 18px;
    border: 0;
    border-bottom: 1px solid var(--sv-line);
    border-radius: var(--sv-r) var(--sv-r) 0 0;
    font-family: var(--sv-font-mono);
    font-size: 13px;
    background: var(--sv-paper);
    color: var(--sv-ink);
  }

  .sv-command__input:focus-visible {
    outline: none;
    border-bottom-color: var(--sv-seed-line);
  }

  .sv-command__input::placeholder {
    color: var(--sv-ink-soft);
  }

  .sv-command__list {
    max-height: 320px;
    overflow-y: auto;
    margin: 0;
    padding: var(--sv-s2) 0 var(--sv-s2);
    list-style: none;
  }

  .sv-command__list ul {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .sv-command__group {
    padding: var(--sv-s2) 18px var(--sv-s1);
    color: var(--sv-ink-faint);
  }

  .sv-command__item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sv-s4);
    padding: var(--sv-s2) 18px;
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
  }

  .sv-command__item--active {
    background: var(--sv-seed-tint);
  }

  .sv-command__hint {
    color: var(--sv-ink-faint);
  }

  .sv-command__none {
    padding: var(--sv-s4) 18px;
    font-size: 13px;
    color: var(--sv-ink-soft);
  }

  /* v0.11 · a result that cannot be opened from here. */
  .sv-command__item[aria-disabled='true'] {
    color: var(--sv-ink-faint);
    cursor: not-allowed;
  }
}
